module.exports = rows.map(([name, payload, ask, notification], index) => ({
  id: 'X' + String(index + 1).padStart(2, '0'), name, payload,
  command: "echo '" + payload.replace(/'/g, "''") + "'",
  expectedAsk: ask,
  // null means advisory behavior is not a pass/fail criterion for this row.
  expectedNotification: notification === null ? null : ask
}));
